<?php require 'config.php';head('Events');?><section class="hero"><h1>Discover your next event ✦</h1><p>Find events and reserve your seat.</p></section><h2>Available events</h2><div class="grid"><?php foreach($db->query('SELECT * FROM events WHERE active=1 ORDER BY event_date') as $e):?><article class="card"><div class="art">✦</div><h3><?=h($e['title'])?></h3><p><?=h($e['description'])?></p><p>📍 <?=h($e['venue'])?></p><p>📅 <?=h($e['event_date'])?></p><a class="btn" href="event.php?id=<?=h($e['id'])?>">View event</a></article><?php endforeach;?></div><?php foot();?>